?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daftar Motor - Rental Motor</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header><a class="brand" href="../index.php"><h1>Rental Motor</h1></a><nav><ul><li><a href="../index.php">Keluar</a></li><li><a href="list.php">Daftar Motor</a></li><?php if(!$customer): ?><li><a href="tambah.php">Tambah Motor</a></li><li><a href="../penyewaan_list.php">Pesanan Penyewaan</a></li><?php endif; ?></ul></nav></header><main><section><h2>Daftar Motor</h2><p><?php echo $customer?'Katalog motor yang tersedia untuk pelanggan.':'Kelola armada motor rental.'; ?></p><?php if($flash): ?><p class="flash flash-success"><?php echo htmlspecialchars($flash); ?></p><?php endif; ?><?php if(!$customer): ?><p><a href="tambah.php">Tambah Motor</a> | <a href="../penyewaan_list.php">Lihat Pesanan</a></p><?php endif; ?><div class="table-responsive"><table><thead><tr><th>Motor</th><th>Merk</th><th>Tahun</th><th>Plat Nomor</th><th>Tarif/Hari</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($motor as $i=>$m): ?><tr><td><?php echo htmlspecialchars($m['nama_motor']); ?></td><td><?php echo htmlspecialchars($m['merk']); ?></td><td><?php echo $m['tahun']; ?></td><td><?php echo htmlspecialchars($m['plat_nomor']); ?></td><td>Rp <?php echo number_format($m['tarif_harian'],0,',','.'); ?></td><td><?php echo htmlspecialchars(ucfirst($m['status'])); ?></td><td><?php if($customer&&$m['status']==='tersedia'): ?><a class="action-edit" href="pesan.php?index=<?php echo $i; ?>">Pesan</a><?php elseif($customer): ?>Tidak tersedia<?php else: ?><a href="tambah.php?edit=<?php echo $i; ?>">Edit</a><form method="post" action="proses_hapus.php" style="display:inline"><input type="hidden" name="index" value="<?php echo $i; ?>"><button>Hapus</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></main><footer><p>&copy;